import { useChat } from "@ai-sdk/react";
import { AgentThinking } from "@mizen-labs/ui";

export function AssistantThinking() {
	const { messages, status } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	const parts = reply?.parts ?? [];
	const reasoning = parts
		.flatMap((part) => (part.type === "reasoning" ? [part.text] : []))
		.join("\n\n");
	const answering = parts.some((part) => part.type === "text" && part.text);
	// Thinking until the first words of the answer arrive.
	const thinking =
		(status === "submitted" || status === "streaming") && !answering;
	if (!(thinking || reasoning)) return null;
	return (
		<AgentThinking
			content={reasoning}
			status={thinking ? "streaming" : "complete"}
		/>
	);
}

