import { useChat } from "@ai-sdk/react";
import { ToolCallGroup, type ToolCallState } from "@mizen-labs/ui";

function statusOf(part: { state: string; approval?: { approved?: boolean } }): ToolCallState {
	if (part.state === "approval-requested") return "approval";
	if (part.state === "output-available") return "complete";
	if (part.state === "output-error") return "error";
	if (part.state === "output-denied" || part.approval?.approved === false) {
		return "denied";
	}
	return "running"; // input-streaming, input-available, approval-responded
}

export function AssistantTools() {
	const { addToolApprovalResponse, messages } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	const calls = (reply?.parts ?? []).flatMap((part) => {
		if (!part.type.startsWith("tool-")) return [];
		return [
			{
				error: part.errorText,
				id: part.toolCallId,
				input: part.input,
				name: part.type.slice("tool-".length),
				onApprove: () =>
					addToolApprovalResponse({ approved: true, id: part.approval.id }),
				onDeny: () =>
					addToolApprovalResponse({ approved: false, id: part.approval.id }),
				output: part.output,
				status: statusOf(part),
			},
		];
	});
	return calls.length > 0 ? <ToolCallGroup calls={calls} /> : null;
}

import { fetchServerSentEvents, useChat } from "@tanstack/ai-react";
import { ToolCallGroup, type ToolCallState } from "@mizen-labs/ui";

const status: Record<string, ToolCallState> = {
	"approval-requested": "approval",
	complete: "complete",
	error: "error",
};

export function AssistantTools() {
	const { messages } = useChat({
		connection: fetchServerSentEvents("/api/chat"),
	});
	const reply = messages.findLast((message) => message.role === "assistant");
	const calls = (reply?.parts ?? []).flatMap((part) =>
		part.type === "tool-call"
			? [
					{
						id: part.id,
						input: part.input,
						name: part.name,
						output: part.output,
						// awaiting-input, input-streaming, input-complete, approval-responded
						status: status[part.state] ?? "running",
						// Answer approvals with your app's handler for part.approval.
					},
				]
			: []
	);
	return calls.length > 0 ? <ToolCallGroup calls={calls} /> : null;
}

import { useChat } from "@ai-sdk/react";
import { Message, StreamingText } from "@mizen-labs/ui";

function textOf(message: { parts: { text?: string; type: string }[] }) {
	return message.parts
		.flatMap((part) => (part.type === "text" ? [part.text] : []))
		.join("");
}

export function Thread() {
	const { error, messages, regenerate, sendMessage, status } = useChat();
	return messages.map((message, index) => {
		const last = index === messages.length - 1;
		if (message.role === "user") {
			return (
				<Message
					from="user"
					key={message.id}
					// An error before any reply leaves the person's message last.
					onRetry={() => regenerate()}
					status={error && last ? "failed" : "sent"}
					// A messageId replaces that message and runs the turn again.
					onEdit={(text) => sendMessage({ messageId: message.id, text })}
				>
					{textOf(message)}
				</Message>
			);
		}
		return (
			<Message from="agent" key={message.id}>
				{/* AgentThinking and ToolCallGroup go here; see their pages. */}
				<StreamingText
					content={textOf(message)}
					status={last && status === "streaming" ? "streaming" : "complete"}
				/>
			</Message>
		);
	});
}

import { fetchServerSentEvents, useChat } from "@tanstack/ai-react";
import { Message, StreamingText } from "@mizen-labs/ui";

function textOf(message: { parts: { content?: string; type: string }[] }) {
	return message.parts
		.flatMap((part) => (part.type === "text" ? [part.content] : []))
		.join("");
}

export function Thread({ onEdit }: { onEdit: (id: string, text: string) => void }) {
	const { error, isLoading, messages, reload } = useChat({
		connection: fetchServerSentEvents("/api/chat"),
	});
	return messages.map((message, index) =>
		message.role === "user" ? (
			<Message
				from="user"
				key={message.id}
				onRetry={reload}
				status={error && index === messages.length - 1 ? "failed" : "sent"}
				// Your handler drops the later turns and sends the new text.
				onEdit={(text) => onEdit(message.id, text)}
			>
				{textOf(message)}
			</Message>
		) : (
			<Message from="agent" key={message.id}>
				<StreamingText
					content={textOf(message)}
					status={isLoading && index === messages.length - 1 ? "streaming" : "complete"}
				/>
			</Message>
		)
	);
}

import { useChat } from "@ai-sdk/react";
import { Sources, type SourcesItem } from "@mizen-labs/ui";

function sourcesOf(message: { parts: { type: string }[] }): SourcesItem[] {
	return message.parts.flatMap((part) => {
		if (part.type === "source-url") {
			return [{ href: part.url, title: part.title }];
		}
		if (part.type === "source-document") {
			return [{ title: part.title }];
		}
		return [];
	});
}

export function ReplySources() {
	const { messages } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	// Sources drops repeats, so a page cited twice shows once.
	return reply ? <Sources sources={sourcesOf(reply)} /> : null;
}

