import { useChat } from "@ai-sdk/react";
import { TaskList, type TaskListStep } from "@mizen-labs/ui";

// Your agent streams its plan as a data part, such as data-plan, and
// updates each step's status as it works.
type PlanPart = {
	data: { steps: TaskListStep[]; title: string };
	type: "data-plan";
};

export function AgentPlan({ onApprove }: { onApprove: () => void }) {
	const { messages, status } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	const plan = reply?.parts.findLast(
		(part): part is PlanPart => part.type === "data-plan"
	);
	if (!plan) return null;
	return (
		<TaskList
			// Ask before running while the agent waits for an answer.
			approval={status === "ready" && plan.data.steps.every((step) => step.status === "pending")}
			onApprove={onApprove}
			steps={plan.data.steps}
			title={plan.data.title}
		/>
	);
}

