import { useChat } from "@ai-sdk/react";
import { InlineCitation, type InlineCitationSource, Text } from "@mizen-labs/ui";

// Render text parts as they come, and each source-url part as a chip where
// it appears in the reply.
export function CitedReply() {
	const { messages } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	return (
		<Text>
			{reply?.parts.map((part, index) => {
				if (part.type === "text") return part.text;
				if (part.type === "source-url") {
					const source: InlineCitationSource = { href: part.url, title: part.title };
					return <InlineCitation key={index} sources={[source]} />;
				}
				return null;
			})}
		</Text>
	);
}

