import { useChat } from "@ai-sdk/react";
import { ApprovalCard } from "@mizen-labs/ui";

// Render a tool part that waits for approval, or one that was decided.
export function ToolApproval({ part }: { part: ToolPart }) {
	const { addToolApprovalResponse } = useChat();
	if (part.state === "approval-requested" && !part.approval.isAutomatic) {
		return (
			<ApprovalCard
				description={part.approval.requestReason}
				details={[{ label: "Command", value: part.input.command }]}
				onApprove={() =>
					addToolApprovalResponse({ approved: true, id: part.approval.id })
				}
				// A note reaches the model with the denial.
				onDeny={({ note }) =>
					addToolApprovalResponse({
						approved: false,
						id: part.approval.id,
						reason: note,
					})
				}
				status="pending"
				title={`Run ${part.input.command}`}
			/>
		);
	}
	if (part.approval?.approved === undefined) return null;
	return (
		<ApprovalCard
			automatic={part.approval.isAutomatic}
			note={part.approval.reason}
			status={part.approval.approved ? "approved" : "denied"}
			title={`Run ${part.input.command}`}
		/>
	);
}

import { ApprovalCard } from "@mizen-labs/ui";

// part is a tool-call part in the approval-requested state. The docs do not
// show how to answer it, so pass your app's handler.
export function ToolApproval({ part, respond }: { part: { input: { command: string } }; respond: (approved: boolean, note?: string) => void }) {
	return (
		<ApprovalCard
			onApprove={() => respond(true)}
			onDeny={({ note }) => respond(false, note)}
			status="pending"
			title={`Run ${part.input.command}`}
		/>
	);
}

import { useChat } from "@ai-sdk/react";
import { QuestionCard, type QuestionCardQuestion } from "@mizen-labs/ui";

// askQuestions is a client-side tool: the model sends the questions as its
// input, and the person's answers become its output.
export function AskQuestions({ part }: { part: AskQuestionsPart }) {
	const { addToolOutput } = useChat();
	const questions: QuestionCardQuestion[] = part.input.questions;
	if (part.state === "output-available") {
		return (
			<QuestionCard answers={part.output} questions={questions} status="answered" />
		);
	}
	return (
		<QuestionCard
			onSubmit={(answers) =>
				addToolOutput({
					output: answers,
					tool: "askQuestions",
					toolCallId: part.toolCallId,
				})
			}
			questions={questions}
			status="pending"
		/>
	);
}

import { QuestionCard, type QuestionCardQuestion } from "@mizen-labs/ui";

// A client tool whose input is the questions. Return the answers as its
// result with your app's handler for client tools.
export function AskQuestions({ part, answer }: { part: { input?: { questions: QuestionCardQuestion[] }; output?: Record<string, string[]> }; answer: (answers: Record<string, string[]>) => void }) {
	if (!part.input) return null;
	return (
		<QuestionCard
			answers={part.output}
			onSubmit={answer}
			questions={part.input.questions}
			status={part.output ? "answered" : "pending"}
		/>
	);
}

import { useChat } from "@ai-sdk/react";
import {
	Composer,
	ComposerInput,
	Conversation,
	ConversationContent,
	ConversationFooter,
	getComposerText,
	Message,
	StreamingText,
} from "@mizen-labs/ui";

export function Chat() {
	const { messages, sendMessage, status } = useChat();
	const streaming = status === "submitted" || status === "streaming";
	return (
		<Conversation>
			<ConversationContent busy={streaming}>
				{messages.map((message) =>
					message.role === "user" ? (
						<Message from="user" key={message.id}>
							{textOf(message)}
						</Message>
					) : (
						<Message from="agent" key={message.id}>
							<StreamingText content={textOf(message)} status={streaming ? "streaming" : "complete"} />
						</Message>
					)
				)}
			</ConversationContent>
			<ConversationFooter>
				<Composer onSubmit={(value) => sendMessage({ text: getComposerText(value) })}>
					<ComposerInput aria-label="Message" />
				</Composer>
			</ConversationFooter>
		</Conversation>
	);
}

