import { useChat } from "@ai-sdk/react";
import { Terminal } from "@mizen-labs/ui";

export function CommandRun({ part, message }: { message: UIMessage; part: RunCommandPart }) {
	const live = message.parts.findLast(
		(other) => other.type === "data-output" && other.id === part.toolCallId
	);
	if (part.state === "output-available") {
		return (
			<Terminal
				command={part.input.command}
				exitCode={part.output.exitCode}
				output={part.output.output}
				status={part.output.exitCode === 0 ? "complete" : "error"}
			/>
		);
	}
	return (
		<Terminal
			command={part.input?.command ?? ""}
			output={live?.data.output}
			status="running"
		/>
	);
}

import { Terminal } from "@mizen-labs/ui";

export function CommandRun({ part }: { part: { input: { command: string }; output?: { exitCode: number; output: string } } }) {
	const result = part.output;
	return (
		<Terminal
			command={part.input.command}
			exitCode={result?.exitCode}
			output={result?.output}
			status={result ? (result.exitCode === 0 ? "complete" : "error") : "running"}
		/>
	);
}

import { useChat } from "@ai-sdk/react";
import { StreamingText, type StreamingTextSource } from "@mizen-labs/ui";

export function AssistantReply() {
	const { messages, regenerate, status } = useChat();
	const reply = messages.findLast((message) => message.role === "assistant");
	if (!reply) return null;
	const content = reply.parts
		.flatMap((part) => (part.type === "text" ? [part.text] : []))
		.join("");
	const sources: StreamingTextSource[] = reply.parts.flatMap((part) => {
		if (part.type === "source-url") return [{ href: part.url, title: part.title }];
		if (part.type === "source-document") return [{ title: part.title }];
		return [];
	});
	return (
		<StreamingText
			content={content}
			onRetry={() => regenerate()}
			sources={sources}
			status={
				status === "error"
					? "error"
					: status === "streaming" || status === "submitted"
						? "streaming"
						: "complete"
			}
		/>
	);
}

